fn rjust(orig: Vec<char>, width: u8, fillchar: char) -> Vec<char> {
    let orig_len = orig.len() as u8; // Get the length of the original vector as u8
    let target_len = width.max(orig_len); // Determine the target length

    // Create a new vector with the target length filled with the fill character
    let mut result = vec![fillchar; target_len as usize];

    // If the original length is less than the target length, copy the original characters
    if orig_len < target_len {
        let start_index = (target_len - orig_len) as usize; // Calculate where to start copying
        result[start_index..].copy_from_slice(&orig); // Copy the original characters to the end
    } else {
        // If the original length is greater than or equal to the target length, just return orig
        return orig;
    }

    result // Return the right-justified vector
}